parameters.jsCode:
const j = $json;
const raw = j.merged_response || (Array.isArray(j.content) ? j.content.filter(c => c.type === 'text').map(c => c.text).join('') : '') || j.text || j.output || '';
const limpio = String(raw).replace(/```json|```/g, '').trim();
const ini = limpio.indexOf('{');
const fin = limpio.lastIndexOf('}');
if (ini === -1 || fin === -1) throw new Error('La IA no devolvió JSON completo. Respuesta recibida: ' + limpio.slice(0, 300).replace(/\s+/g, ' '));
const r = JSON.parse(limpio.slice(ini, fin + 1));
const categorias = ['Facturacion', 'Tecnico', 'Cuenta y Acceso', 'Comercial', 'Otro'];
const sentimientos = ['Positivo', 'Neutral', 'Negativo'];
const prioridad = Math.min(5, Math.max(1, parseInt(r.prioridad, 10) || 3));
if (!r.borrador || String(r.borrador).trim().length < 10) throw new Error('La IA devolvió un borrador vacío.');
return { json: {
  categoria: categorias.includes(r.categoria) ? r.categoria : 'Otro',
  prioridad,
  sentimiento: sentimientos.includes(r.sentimiento) ? r.sentimiento : 'Neutral',
  resumen: String(r.resumen || '').trim(),
  borrador: String(r.borrador).trim(),
  razonamiento: String(r.razonamiento || '').trim()
} };
